-- Dihasilkan oleh tools/mysql2pg.py — jangan diedit tangan.

CREATE TABLE IF NOT EXISTS company (
  company_id varchar(50) NOT NULL,
  company_name varchar(255) NOT NULL,
  phone varchar(15) NOT NULL,
  fax varchar(20) NOT NULL,
  email varchar(50) NOT NULL,
  alamat varchar(255) NOT NULL,
  igd_phone varchar(20) NOT NULL,
  slogan varchar(50) NOT NULL,
  hospital_name varchar(255) NOT NULL,
  logo_hospital varchar(200) NOT NULL,
  company_description text NOT NULL,
  link_youtube_profile text NOT NULL,
  visi text NOT NULL,
  misi text NOT NULL
);

CREATE TABLE IF NOT EXISTS dokter (
  id_dokter varchar(100) NOT NULL,
  nama_dokter varchar(100) NOT NULL,
  ket text NOT NULL,
  images varchar(100) NOT NULL,
  id_poli varchar(100) NOT NULL
);

CREATE TABLE IF NOT EXISTS facility (
  id_facility varchar(100) NOT NULL,
  facility_name varchar(255) NOT NULL,
  facility_description text NOT NULL,
  facility_image varchar(200) NOT NULL
);

CREATE TABLE IF NOT EXISTS hospital (
  hospital_id varchar(20) NOT NULL,
  title varchar(200) NOT NULL,
  content text NOT NULL,
  link_hospital varchar(200) NOT NULL,
  images varchar(200) NOT NULL
);

CREATE TABLE IF NOT EXISTS jadwal_dokter (
  id_jadwal varchar(100) NOT NULL,
  hari varchar(100) NOT NULL,
  jammulai time NOT NULL,
  jamselesai time NOT NULL,
  id_dokter varchar(100) NOT NULL,
  id_poli varchar(100) NOT NULL
);

CREATE TABLE IF NOT EXISTS news (
  news_id varchar(100) NOT NULL,
  title varchar(200) NOT NULL,
  content text NOT NULL,
  create_date timestamp DEFAULT NULL,
  news_images varchar(200) NOT NULL
);

CREATE TABLE IF NOT EXISTS poli (
  id_poli varchar(100) NOT NULL,
  nama_poli varchar(100) NOT NULL,
  ket text NOT NULL,
  images varchar(100) NOT NULL
);

CREATE TABLE IF NOT EXISTS slide_images (
  id_slide varchar(11) NOT NULL,
  images varchar(200) NOT NULL
);

CREATE TABLE IF NOT EXISTS tb_admin (
  id integer NOT NULL,
  nama varchar(200) NOT NULL,
  "user" varchar(255) NOT NULL,
  password varchar(12) NOT NULL,
  images varchar(255) NOT NULL
);

CREATE TABLE IF NOT EXISTS users (
  user_id integer NOT NULL,
  username varchar(40) NOT NULL,
  password varchar(40) NOT NULL,
  name varchar(100) NOT NULL,
  addres varchar(200) NOT NULL,
  level integer NOT NULL
);

CREATE TABLE IF NOT EXISTS penjamin (
  id integer GENERATED BY DEFAULT AS IDENTITY NOT NULL,
  nama varchar(120) NOT NULL,
  kategori varchar(60) NOT NULL DEFAULT 'Asuransi',
  urutan integer NOT NULL DEFAULT 0,
  aktif smallint NOT NULL DEFAULT 1,
  PRIMARY KEY (id),
  CONSTRAINT penjamin_uniq_nama UNIQUE (nama)
);

CREATE TABLE IF NOT EXISTS promo (
  id integer GENERATED BY DEFAULT AS IDENTITY NOT NULL,
  judul varchar(180) NOT NULL,
  deskripsi text NOT NULL,
  gambar varchar(200) NOT NULL DEFAULT '',
  link varchar(200) NOT NULL DEFAULT '',
  mulai date DEFAULT NULL,
  selesai date DEFAULT NULL,
  aktif smallint NOT NULL DEFAULT 1,
  dibuat timestamp DEFAULT now(),
  PRIMARY KEY (id)
);

CREATE TABLE IF NOT EXISTS testimoni (
  id integer GENERATED BY DEFAULT AS IDENTITY NOT NULL,
  nama varchar(120) NOT NULL,
  isi text NOT NULL,
  foto varchar(200) NOT NULL DEFAULT '',
  rating smallint NOT NULL DEFAULT 5,
  tanggal date DEFAULT NULL,
  tampil smallint NOT NULL DEFAULT 1,
  PRIMARY KEY (id)
);

CREATE TABLE IF NOT EXISTS pendaftaran (
  id integer GENERATED BY DEFAULT AS IDENTITY NOT NULL,
  kode varchar(20) NOT NULL,
  nama_pasien varchar(150) NOT NULL,
  telepon varchar(25) NOT NULL,
  tanggal_lahir date DEFAULT NULL,
  id_poli varchar(100) NOT NULL DEFAULT '',
  id_dokter varchar(100) NOT NULL DEFAULT '',
  tanggal_kunjungan date DEFAULT NULL,
  penjamin varchar(120) NOT NULL DEFAULT '',
  no_penjamin varchar(60) NOT NULL DEFAULT '',
  keluhan text NOT NULL,
  status varchar(20) NOT NULL DEFAULT 'baru',
  dibuat timestamp DEFAULT now(),
  ip varchar(45) NOT NULL DEFAULT '',
  PRIMARY KEY (id),
  CONSTRAINT pendaftaran_uniq_kode UNIQUE (kode)
);

CREATE TABLE IF NOT EXISTS karier (
  id integer GENERATED BY DEFAULT AS IDENTITY NOT NULL,
  posisi varchar(150) NOT NULL,
  unit varchar(120) NOT NULL DEFAULT '',
  jenis varchar(40) NOT NULL DEFAULT 'Full time',
  deskripsi text NOT NULL,
  kualifikasi text NOT NULL,
  aktif smallint NOT NULL DEFAULT 1,
  dibuat date DEFAULT NULL,
  ditutup date DEFAULT NULL,
  PRIMARY KEY (id)
);

CREATE TABLE IF NOT EXISTS lamaran (
  id integer GENERATED BY DEFAULT AS IDENTITY NOT NULL,
  kode varchar(20) NOT NULL,
  nama varchar(150) NOT NULL,
  telepon varchar(25) NOT NULL,
  email varchar(120) NOT NULL DEFAULT '',
  posisi varchar(150) NOT NULL,
  pesan text NOT NULL,
  ip varchar(45) NOT NULL DEFAULT '',
  status varchar(20) NOT NULL DEFAULT 'baru',
  dibuat timestamp DEFAULT now(),
  PRIMARY KEY (id),
  CONSTRAINT lamaran_uniq_kode UNIQUE (kode)
);

CREATE TABLE IF NOT EXISTS pesan_kontak (
  id integer GENERATED BY DEFAULT AS IDENTITY NOT NULL,
  nama varchar(150) NOT NULL,
  email varchar(120) NOT NULL DEFAULT '',
  telepon varchar(25) NOT NULL DEFAULT '',
  topik varchar(60) NOT NULL DEFAULT 'Umum',
  pesan text NOT NULL,
  ip varchar(45) NOT NULL DEFAULT '',
  status varchar(20) NOT NULL DEFAULT 'baru',
  dibuat timestamp DEFAULT now(),
  PRIMARY KEY (id)
);

CREATE TABLE IF NOT EXISTS admin_user (
  id integer GENERATED BY DEFAULT AS IDENTITY NOT NULL,
  username varchar(60) NOT NULL,
  nama varchar(120) NOT NULL DEFAULT '',
  password_hash varchar(255) NOT NULL,
  role varchar(20) NOT NULL DEFAULT 'admin',
  aktif smallint NOT NULL DEFAULT 1,
  terakhir_login timestamp NULL DEFAULT NULL,
  dibuat timestamp DEFAULT now(),
  PRIMARY KEY (id),
  CONSTRAINT admin_user_uniq_username UNIQUE (username)
);

CREATE TABLE IF NOT EXISTS grup_rs (
  id integer GENERATED BY DEFAULT AS IDENTITY NOT NULL,
  nama varchar(120) NOT NULL,
  kota varchar(120) NOT NULL DEFAULT '',
  url varchar(200) NOT NULL DEFAULT '',
  foto varchar(200) NOT NULL DEFAULT '',
  urutan integer NOT NULL DEFAULT 99,
  aktif smallint NOT NULL DEFAULT 1,
  PRIMARY KEY (id)
);

CREATE TABLE IF NOT EXISTS kasur (
  id integer GENERATED BY DEFAULT AS IDENTITY NOT NULL,
  nama_unit varchar(120) NOT NULL,
  kelas varchar(40) NOT NULL DEFAULT '',
  total integer NOT NULL DEFAULT 0,
  terisi integer NOT NULL DEFAULT 0,
  keterangan varchar(255) NOT NULL DEFAULT '',
  urutan integer NOT NULL DEFAULT 99,
  aktif smallint NOT NULL DEFAULT 1,
  diperbarui timestamp DEFAULT now(),
  PRIMARY KEY (id),
  CONSTRAINT kasur_uniq_unit UNIQUE (nama_unit)
);

CREATE TABLE IF NOT EXISTS survei (
  id integer GENERATED BY DEFAULT AS IDENTITY NOT NULL,
  nama varchar(120) NOT NULL DEFAULT '',
  unit varchar(120) NOT NULL DEFAULT '',
  r_pendaftaran smallint NOT NULL DEFAULT 0,
  r_dokter smallint NOT NULL DEFAULT 0,
  r_perawat smallint NOT NULL DEFAULT 0,
  r_fasilitas smallint NOT NULL DEFAULT 0,
  r_kebersihan smallint NOT NULL DEFAULT 0,
  nilai numeric(3,2) NOT NULL DEFAULT 0.00,
  komentar text NULL,
  saran text NULL,
  ip varchar(60) NOT NULL DEFAULT '',
  dibuat timestamp DEFAULT now(),
  PRIMARY KEY (id)
);

-- indeks
CREATE INDEX IF NOT EXISTS idx_promo_idx_aktif ON promo (aktif, selesai);
CREATE INDEX IF NOT EXISTS idx_testimoni_idx_tampil ON testimoni (tampil);
CREATE INDEX IF NOT EXISTS idx_pendaftaran_idx_kunjungan ON pendaftaran (tanggal_kunjungan, id_poli);
CREATE INDEX IF NOT EXISTS idx_karier_idx_aktif ON karier (aktif, ditutup);
CREATE INDEX IF NOT EXISTS idx_pesan_kontak_idx_status ON pesan_kontak (status);
CREATE INDEX IF NOT EXISTS idx_grup_rs_idx_urutan ON grup_rs (urutan);
CREATE INDEX IF NOT EXISTS idx_kasur_idx_aktif ON kasur (aktif, urutan);
CREATE INDEX IF NOT EXISTS idx_survei_idx_dibuat ON survei (dibuat);

