INSERT INTO dokter (id_dokter, nama_dokter, ket, images, id_poli) VALUES
('DR01', 'dr. Azwarto Lubis, Sp.B', 'Dokter bedah adalah dokter spesialis yang mengobati penyakit, cedera, atau kondisi gawat darurat pada tubuh melalui metode bedah (operatif) dan obat-obatan. Untuk menjadi dokter bedah, seseorang harus menyelesaikan pendidikan dan profesi dokter umum, lalu menyelesaikan pendidikan spesialis ilmu bedah.
 ', 'doctor-240802-b5fb4aaea9.jpg', 'P01'),
('DR02', 'dr. Muhammad Aulia Erizal, Sp.B', 'Dokter bedah adalah dokter spesialis yang mengobati penyakit, cedera, atau kondisi gawat darurat pada tubuh melalui metode bedah (operatif) dan obat-obatan. Untuk menjadi dokter bedah, seseorang harus menyelesaikan pendidikan dan profesi dokter umum, lalu menyelesaikan pendidikan spesialis ilmu bedah.
', 'doctor-240919-20c30c2833.jpg', 'P01'),
('DR03', 'dr. Jos Arno M Silitonga, Sp.B', 'Dokter bedah adalah dokter spesialis yang mengobati penyakit, cedera, atau kondisi gawat darurat pada tubuh melalui metode bedah (operatif) dan obat-obatan. Untuk menjadi dokter bedah, seseorang harus menyelesaikan pendidikan dan profesi dokter umum, lalu menyelesaikan pendidikan spesialis ilmu bedah.
', 'doctor-240920-70ed672e1e.jpg', 'P01'),
('DR05', 'dr. Disfahan Sinulingga, Sp. BS', 'Dokter bedah saraf adalah dokter spesialis yang memiliki keahlian dalam mendiagnosis dan melakukan tindakan pembedahan terhadap pasien dengan gangguan sistem saraf, baik pada saraf pusat maupun saraf tepi.', 'doctor-240920-54bf4a52e8.jpg', 'P09'),
('DR06', 'dr. Heri Hendri, Sp.PD', 'Dokter spesialis penyakit dalam adalah dokter spesialis yang menangani pasien dewasa dengan keluhan terkait hampir seluruh organ dalam tubuh, seperti jantung, paru-paru, ginjal, dan sistem pencernaan. Selain itu, dokter spesialis penyakit dalam juga dapat berhubungan dengan kondisi yang memengaruhi tekanan darah, sistem imunitas, dan metabolisme tubuh.
', 'doctor-240920-d9f4431952.jpg', 'P03'),
('DR07', 'dr. Yahsarul Ikhsan Nst, Sp. PD', 'Dokter spesialis penyakit dalam adalah dokter spesialis yang menangani pasien dewasa dengan keluhan terkait hampir seluruh organ dalam tubuh, seperti jantung, paru-paru, ginjal, dan sistem pencernaan. Selain itu, dokter spesialis penyakit dalam juga dapat berhubungan dengan kondisi yang memengaruhi tekanan darah, sistem imunitas, dan metabolisme tubuh.
', 'doctor-250708-497accfa3b.JPG', 'P03'),
('DR08', 'dr. Farik Zarmal, Sp.PD', 'Dokter spesialis penyakit dalam adalah dokter spesialis yang menangani pasien dewasa dengan keluhan terkait hampir seluruh organ dalam tubuh, seperti jantung, paru-paru, ginjal, dan sistem pencernaan. Selain itu, dokter spesialis penyakit dalam juga dapat berhubungan dengan kondisi yang memengaruhi tekanan darah, sistem imunitas, dan metabolisme tubuh.
', 'doctor-240920-e9f45f8c4f.jpg', 'P03'),
('DR09', 'dr. Erni Erdoris Ginting, M.Ked (PD), Sp.PD', 'Dokter spesialis penyakit dalam adalah dokter spesialis yang menangani pasien dewasa dengan keluhan terkait hampir seluruh organ dalam tubuh, seperti jantung, paru-paru, ginjal, dan sistem pencernaan. Selain itu, dokter spesialis penyakit dalam juga dapat berhubungan dengan kondisi yang memengaruhi tekanan darah, sistem imunitas, dan metabolisme tubuh.
', 'doctor-240920-ee64cb0038.jpg', 'P03'),
('DR10', 'dr. Rika Febrianti, Sp.THT-KL', 'Dokter spesialis THT adalah dokter yang memiliki keahlian khusus dalam mengobati penyakit yang berkaitan dengan telinga, hidung, dan tenggorokan. Selain itu, dokter spesialis ini juga bertugas untuk mengatasi sejumlah penyakit yang terjadi di kepala dan leher.', 'doctor-240920-0879168382.jpg', 'P04'),
('DR11', 'dr. Agussalim, M.Ked (ORL-HNS), Sp.THT-KL', 'Dokter spesialis THT adalah dokter yang memiliki keahlian khusus dalam mengobati penyakit yang berkaitan dengan telinga, hidung, dan tenggorokan. Selain itu, dokter spesialis ini juga bertugas untuk mengatasi sejumlah penyakit yang terjadi di kepala dan leher.', 'doctor-240920-006ef00603.jpg', 'P04'),
('DR12', 'dr. Azmeilia Syafitri Lubis, Sp. THT-BKL', 'Dokter spesialis THT adalah dokter yang memiliki keahlian khusus dalam mengobati penyakit yang berkaitan dengan telinga, hidung, dan tenggorokan. Selain itu, dokter spesialis ini juga bertugas untuk mengatasi sejumlah penyakit yang terjadi di kepala dan leher.', 'doctor-240920-41a0712407.jpg', 'P04'),
('DR13', 'dr. Vivianna, M.Ked (Ped), Sp. A', 'Dokter spesialis anak atau ahli pediatri adalah dokter yang memiliki fokus pada kesehatan fisik, mental, dan emosional anak usia 0–18 tahun. Tak hanya sekadar memeriksa, dokter dengan gelar Sp.A ini juga dapat melakukan berbagai prosedur untuk menangani berbagai gangguan yang dialami anak.', 'doctor-240920-be9bb48ebe.jpg', 'P05'),
('DR14', 'dr. Mahadian Ismail Nasution, Sp.A', 'Dokter spesialis anak atau ahli pediatri adalah dokter yang memiliki fokus pada kesehatan fisik, mental, dan emosional anak usia 0–18 tahun. Tak hanya sekadar memeriksa, dokter dengan gelar Sp.A ini juga dapat melakukan berbagai prosedur untuk menangani berbagai gangguan yang dialami anak.', 'doctor-241202-fc932759b8.JPG', 'P05'),
('DR15', 'dr. Andry Miraza, M.Kes., M. Ked (Ped), Sp. A', 'Dokter spesialis anak atau ahli pediatri adalah dokter yang memiliki fokus pada kesehatan fisik, mental, dan emosional anak usia 0–18 tahun. Tak hanya sekadar memeriksa, dokter dengan gelar Sp.A ini juga dapat melakukan berbagai prosedur untuk menangani berbagai gangguan yang dialami anak.', 'doctor-250808-3662d3f101.JPG', 'P05'),
('DR16', 'dr. Trishna, Sp.OG', 'Dokter spesialis OBGYN, merupakan dokter yang memiliki fokus pada bidang reproduksi wanita, baik tentang masalah menstruasi, kemudian kehamilan, persalinan sampai dengan menopause.', 'doctor-240920-b123e935d3.jpg', 'P06'),
('DR17', 'dr. Edwar Ayub, Sp.OG (K)', 'Dokter spesialis OBGYN, merupakan dokter yang memiliki fokus pada bidang reproduksi wanita, baik tentang masalah menstruasi, kemudian kehamilan, persalinan sampai dengan menopause.', 'doctor-240920-dc412894b0.jpg', 'P06'),
('DR18', 'dr. Hasinah M.Ked (Card), Sp.JP', 'Dokter spesialis jantung dan pembuluh darah atau ahli kardiologi merupakan dokter yang berfokus pada diagnosis dan penanganan masalah kesehatan, 
yang berkaitan dengan jantung dan pembuluh darah (kardiovaskuler). ', 'doctor-240920-ca006a9a24.jpg', 'P07'),
('DR19', 'dr. Petrus Suranta Pinem, M.Ked (Cardio), Sp. JP (K)', 'Dokter spesialis jantung dan pembuluh darah atau ahli kardiologi merupakan dokter yang berfokus pada diagnosis dan penanganan masalah kesehatan, 
yang berkaitan dengan jantung dan pembuluh darah (kardiovaskuler). ', 'doctor-250410-f38feae19f.JPG', 'P07'),
('DR20', 'dr. Sheila Dhiene Putri, Sp.JP', 'Dokter spesialis jantung dan pembuluh darah atau ahli kardiologi merupakan dokter yang berfokus pada diagnosis dan penanganan masalah kesehatan, 
yang berkaitan dengan jantung dan pembuluh darah (kardiovaskuler). ', 'doctor-240920-433f3d3aeb.jpg', 'P07'),
('DR21', 'dr. Ardiana Annisa, Sp.Rad', 'Dokter radiologi atau radiologis bertugas melakukan pemeriksaan radiologi untuk mengidentifikasi, mendiagnosis, serta mengobati penyakit melalui prosedur pencitraan atau radiasi. Misalnya, seperti foto rontgen, USG, CT scan, hingga MRI.', 'doctor-240920-fbb3aff470.jpg', 'P15'),
('DR22', 'dr. Deni Setiawan, Sp. Rad', 'Dokter radiologi atau radiologis bertugas melakukan pemeriksaan radiologi untuk mengidentifikasi, mendiagnosis, serta mengobati penyakit melalui prosedur pencitraan atau radiasi. Misalnya, seperti foto rontgen, USG, CT scan, hingga MRI.', 'doctor-240920-4015f9b9d9.jpg', 'P15'),
('DR23', 'dr. Syarifah Yusriani, M.Ked (Oph), Sp. M', 'Dokter Spesialis Mata atau Opthalmology adalah salah satu spesialisasi ilmu kedokteran yang khusus mendalami tentang organ mata dan struktur disekitarnya. Seorang dokter spesialis mata mampu mendeteksi dan mengobati keluhan pada mata dengan meresepkan kacamata maupun obat-obatan sampai tindakan pembedahan seperti pada penggantian lensa mata.', 'doctor-240920-1795cf2b1a.jpg', 'P02'),
('DR24', 'dr. T. Siti Harliza Zubaidah, Sp.M', 'Dokter Spesialis Mata atau Opthalmology adalah salah satu spesialisasi ilmu kedokteran yang khusus mendalami tentang organ mata dan struktur disekitarnya. Seorang dokter spesialis mata mampu mendeteksi dan mengobati keluhan pada mata dengan meresepkan kacamata maupun obat-obatan sampai tindakan pembedahan seperti pada penggantian lensa mata.', 'doctor-240920-6b555d2788.jpg', 'P02'),
('DR25', 'dr. Donal Anjar Simanjuntak, M.Ked (Paru), Sp. P (K)', 'Dokter spesialis paru atau pulmonologist merupakan  dokter ahli yang menangani pasien  mendiagnosis dan merawat pasien yang mengalami gangguan kesehatan pada saluran pernapasan, paru-paru, hingga organ lain yang membantu pernapasan. ', 'doctor-240920-5c69e5c63e.jpg', 'P10'),
('DR26', 'dr. Sukamto, Sp. P', 'Dokter spesialis paru atau pulmonologist merupakan  dokter ahli yang menangani pasien  mendiagnosis dan merawat pasien yang mengalami gangguan kesehatan pada saluran pernapasan, paru-paru, hingga organ lain yang membantu pernapasan. ', 'doctor-240920-224e3bdeeb.jpg', 'P10'),
('DR27', 'dr. Irina Damayanti M.Ked (DV), Sp. DV', 'Dokter spesialis kulit dan kelamin merupakan dokter yang fokus menangani beragam masalah kesehatan kulit dan kelamin, baik pada pria maupun wanita. Tugas dokter spesialis kulit dan kelamin adalah mendiagnosa dan memberikan penanganan sesuai dengan keluhan seperti penyakit kulit, mulut, rambut, kuku, kelenjar keringat, kelenjar minyak, dan pastinya masalah yang berhubungan dengan kelamin.', 'doctor-240920-1e38f2ecd3.jpg', 'P12'),
('DR28', 'dr. Wahyuni Widiyanti Suhoyo, M.Ked (DV), Sp. DV', 'Dokter spesialis kulit dan kelamin merupakan dokter yang fokus menangani beragam masalah kesehatan kulit dan kelamin, baik pada pria maupun wanita. Tugas dokter spesialis kulit dan kelamin adalah mendiagnosa dan memberikan penanganan sesuai dengan keluhan seperti penyakit kulit, mulut, rambut, kuku, kelenjar keringat, kelenjar minyak, dan pastinya masalah yang berhubungan dengan kelamin.', 'doctor-240920-58608b475c.jpg', 'P12'),
('DR29', 'dr. Julia Evalina Gingting, Sp. S', 'Dokter spesialis neurologi atau spesialis saraf merupakan dokter yang bertugas menangani 
berbagai keluhan terkait dengan gangguan otak dan saraf, seperti penyakit Parkinson, penyakit Alzheimer, kejang, demensia, cedera otak, stroke, dan lain-lain. Dokter spesialis saraf dapat menangani keluhan pasien melalui tindakan medis yang sesuai,  perawatan lanjutan, hingga evaluasi hasil pengobatan.

', 'doctor-240920-eab39fb36f.jpg', 'P13'),
('DR30', 'dr. Rita Sibarani, M.Ked (Neu), Sp. S', 'Dokter spesialis neurologi atau spesialis saraf merupakan dokter yang bertugas menangani 
berbagai keluhan terkait dengan gangguan otak dan saraf, seperti penyakit Parkinson, penyakit Alzheimer, kejang, demensia, cedera otak, stroke, dan lain-lain. Dokter spesialis saraf dapat menangani keluhan pasien melalui tindakan medis yang sesuai, 
perawatan lanjutan, hingga evaluasi hasil pengobatan.

', 'doctor-240920-387da2aaa0.jpg', 'P13'),
('DR31', 'dr. Hasanul Arifin, Sp. N', 'Dokter spesialis neurologi atau spesialis saraf merupakan dokter yang bertugas menangani  berbagai keluhan terkait dengan gangguan otak dan saraf, seperti penyakit Parkinson, penyakit Alzheimer, kejang, demensia, cedera otak, stroke, dan lain-lain. Dokter spesialis saraf dapat menangani keluhan pasien melalui tindakan medis yang sesuai,  perawatan lanjutan, hingga evaluasi hasil pengobatan.

', 'doctor-240920-63417d1afb.jpg', 'P13'),
('DR32', 'dr. Benni Azhari, Sp.KFR', 'Kedokteran Fisik dan Rehabilitasi (KFR) atau Fisiatri adalah spesialisasi kedokteran yang berkenaan dengan diagnosis, evaluasi, dan penatalaksanaan pasien yang mengalami disfungsi dan disabilitas fisik dan/atau kognitif.

Spesialisasi ini meliputi diagnosis dan pengobatan pasien dengan nyeri atau kondisi yang membatasi fungsi, penatalaksanaan ko-morbiditas dan disfungsi lainnya, prosedur injeksi diagnostik dan terapeutik, elektrodiagnosis, serta pencegahan komplikasi disabilitas dari kondisi sekunder. ', 'doctor-240920-d5cb55fdc1.jpg', 'P16'),
('DR33', 'drg. Nur Suri Wulandari', 'Seorang dokter gigi memiliki keahlian khusus dalam mendiagnosis, mengobati, dan mencegah masalah kesehatan atau kelainan pada gigi. Tak hanya itu, peran dokter gigi juga mencakup penanganan sejumlah gangguan pada gusi dan mulut.', 'doctor-240920-3e94985b1f.jpg', 'P17'),
('DR34', 'dr. Juni Hardi Tarigan, Sp. OG', 'Dokter spesialis OBGYN, merupakan dokter yang memiliki fokus pada bidang reproduksi wanita, baik tentang masalah menstruasi, kemudian kehamilan, persalinan sampai dengan menopause.', 'doctor-241108-60199b3380.jpg', 'P06');

INSERT INTO facility (id_facility, facility_name, facility_description, facility_image) VALUES
('facility-1', 'INSTALASI GAWAT DARURAT (IGD)', 'Pelayanan Unit Gawat Darurat (UGD) adalah salah satu
ujung tombak pelayanan kesehatan di sebuah rumah sakit.
RSU Bidadari memiliki layanan UGD 24 jam dengan 14
dokter umum yang telah tersertivikasi pelayanan gawat
darurat.
', 'facility-241203-bce850dfcd.jpg'),
('facility-10', 'RAWAT INAP', 'Rawat inap adalah pelayanan kesehatan perorangan, yang meliputi observasi, diagnosa, pengobatan, keperawatan, rahabilitasi medik, dengan menginap di ruang rawat inap pada sarana kesehatan rumah sakit dimana dengan alasan medik penderita harus menginap. ', 'facility-241203-f26002eb33.jpg'),
('facility-11', 'BANK DARAH', 'Bank Darah Rumah Sakit berfungsi untuk menjaga tersedianya darah untuk tranfusi
yang aman, berkualitas dan dalam jumlah yang cukup untuk mendukung
pelayanan kesehatan di rumah sakit umum Bidadari Binjai.
', 'facility-241203-11b0534a0b.jpg'),
('facility-12', 'UNIT LAUNDRY', 'Unit laundry rumah sakit adalah unit pelayanan yang bertugas mencuci linen rumah sakit. Linen adalah istilah untuk semua produk tekstil di rumah sakit. RSU bidarari bekerja sama dengan RSU Putri Bidadari untuk pengelolaan linen.', 'facility-241203-f7db436351.jpg'),
('facility-13', 'AREA PARKIR', 'RSU Bidadari Binjai menyediakan lahan parkir yang luas dan aman untuk Mobil dan Sepeda Motor,
dengan sistem parkir yang terkomputerisasi ', 'facility-241203-32f068d499.jpg'),
('facility-14', 'MUSHOLLA', 'Selain menyediakan layanan Medis dan Penunjangnya, RSU Mahkota Bidadari juga
menyediakan layanan rohani bagi para pengunjung Rumah sakit untuk melaksanakan
kegiatan keagamaan', 'facility-250106-50c5caf606.jpg'),
('facility-15', 'CATHLAB - KATETERISASI JANTUNG', 'Masyarakat Binjai dan sekitarnya kini tak perlu jauh-jauh keluar Kota atau bahkan keluar negeri untuk mendapatkan Pelayanan Kateterisasasi Jantung dan  Pembuluh  darah, sebab  RSU. Bidadari  telah  menghadirkan  Pelayanan  Kateterisasasi Jantung dan Pembuluh darah (CATHLAB)', 'facility-250106-e1c80a691a.jpg'),
('facility-16', 'UNIT DIALISIS', 'Hemodialisis memberikan pelayanan cuci darah bagi pasien rawat jalan dan rawat inap dengan didukung tim dokter ahli yang terdiri dari Nephrologist.', 'facility-250106-dba699dedd.jpg'),
('facility-17', 'ATM CENTRE', 'Untuk mempermudah sarana transaksi, RSU Bidadari menyediakan ATM Center sebagai sarana penarikan uang tunai. (Bank BRI).', 'facility-250106-e2260201e6.jpg'),
('facility-18', 'UNIT GIZI', 'Pelayanan gizi disesuaikan berdasarkan keadaan klinis, status gizi , dan status metabolisme tubuh pasien. Keadaan gizi pasien sangat berpengaruh pada proses penyembuhan penyakit. Oleh karena itu Unit gizi berfungsi sebagai :
• Pengadaan dan penyediaan makanan.
• Pelayanan gizi rawat inap.
• Penyuluhan dan konsultasi gizi.
• Penelitian dan pengembangan gizi terapan.', 'facility-250710-22203e3869.JPG'),
('facility-2', 'RAWAT INAP', 'Pelayanan Rawat Inap terdiri dari 201 Tempat tidur yang tersebar dari kelas III, II, I,
VIP, ICU, NICU & BABY', 'facility-250106-dcd6e87f41.jpg'),
('facility-3', 'POLIKLINIK', 'Didukung oleh tenaga medis dokter spesialis dan perawat berpengalaman, Poliklinik RS
Bidadari memiliki ruang poliklinik yang mampu melayani sampai dengan 300
pasien per-hari. dengan djadwal poliklinik dari pagi sampai sore.', 'facility-250106-da47d1f3ce.jpg'),
('facility-4', 'RADIOLOGI', 'CT-Scan (dengan dan tanpa kontras)
Xcomputerized Radiogra (Foto ontgen)
USG Abdomen
', 'facility-250106-ef5ed6d333.jpg'),
('facility-5', 'ICU', 'ICU sebagai salah satu unit perawatan intensif
dilengkapi peralatan canggih dengan monitor central
yang memungkinkan pemanatauan ketat', 'facility-250106-27e8cf02fd.jpg'),
('facility-6', 'NICU', 'Neonatal Intensive Care Unit atau yang biasa disingkat dengan
NICU merupakan ruang perawatan intensif di RSU Bidadari Binjai
yang difungsikan untuk merawat bayi prematur dan bayi baru lahir sampai
 usia 30 (tigapuluh) hari.', 'facility-250106-df2569d49e.jpg'),
('facility-7', 'LABORATORIUM', 'Laboratorium Patologi Klinik RSU Bidadari merupakan unit pelayanan diagnostik dengan menggunakan sistem mutu yang memenuhi  standar laboratorium patologi mencakup peralatan yang mengikuti perkembangan teknologi.', 'facility-250106-c74c5f834e.jpg'),
('facility-8', 'FARMASI', 'Menyediakan obat-obatan untuk unit perawatan dan bidang – bidang lain.
Mengarsipkan resep-resep baik untuk pasien rawat jalan maupun pasien rawat inap.
Membuat obat-obatan. Menyalurkan, membagikan obat-obatan narkotika dan obat yang diresepkan. Menyimpan dan membagikan preparat-preparat biologis.
Membuat, menyiapkan, mensterilkan preparat parenteral.', 'facility-250106-4a2e119650.jpg'),
('facility-9', 'KAMAR BERSALIN', 'RSU Bidadari memiliki fasilitas kamar bersalin (VK) sebagi tempat Pertolongan persalinan baik normal maupun dengan penyulit Pemeriksaan penunjang diagnostik dan Tindakan medis yang bersifat diagnostik.
', 'facility-250106-21119d0633.jpg');

