INSERT INTO news (news_id, title, content, create_date, news_images) VALUES
('NEWS-01', 'RSU BIDADARI BINJAI BEKERJA SAMA DENGAN IDI KOTA BINJAI MENGADAKAN SEMINAR & WORKSHOP KEGAWATDARURATAN KARDIOVASKULAR', 'Rumah Sakit Umum Bidadari Binjai bekerja sama dengan Ikatan Dokter Indonesia (IDI) Cabang kota Binjai mengadakan kegiatan seminar dan workshop  Kegawat Daruratan Kardiovaskular yang  telah dilaksanakan pada 25 Februari 2023. Kegiatan ini diadakan gratis bagi tenaga kesehatan untuk meningkatkan kompentensi dalam penanganan kedaruratan kardiovaskular. Dalam kegiatan  ini juga diisi oleh pembicara yang kompeten dibidang spelialis jantung dengan tema seminar yang berbeda-beda tiap pengisi materi.

Diisi oleh tiga pemateri diantaranya adalah:
Pemateri pertama dibawakan oleh dr. Hasinah M.Ked (Card), Sp.JP dengan tema  "Diagnosis and Management of Acute Coronary Syndrome".
Pemateri kedua oleh dr. Sheila Dhiene Putri, Sp.JP dengan tema "Acute Heart Failure: From Guideline to Pratice" dan 
Pemateri Ketiga dibawakan ole dr. Muhammad Ginanjar, Sp.JP dengan Tema "Basic ECG Interpretation and Emergency ECG in Daily Pratice, How to Manage". Ketiga pembicara merupaka dokter spesialis jantung yang saat ini bertugas di RSU Bidadari Binjai.

Dalam Kegiatan seminar dan workhsop ini juga diisi oleh dua pemateri lainnya yaitu dr. Dedy Asmara mebawakan materi P2KB (Program Pengembangan Keprofesian Berkelanjutan). Serta pemateri Mohd Ikhsan dan KBRI New Delhi membawakan materi menganai "Potensi India menjadi Destinasi Fasilitas Transplantasi Hati dan Ginjal dengan Cost terjangkau dan Fasilitas Lengkap. Diharapkan dalam pelaksanaan kegiatan ini dapan menjadi wadah bagi para Tenaga Kesehatan yang bertugas baik di Fasilitas Kesehatan Tingtak Pertama maupun tingkat Lanjutan dapat meningkatkan kemampuan dalam menangani kegawatdaruratan jantung.
', NULL, 'news-231124-25c47cae25.jpg'),
('NEWS-02', 'TELAH HADIR PELAYANAN REHABILITASI MEDIK DAN FISIOTERAPI DI RSU BIDADARI BINJAI', 'Rumah Sakit Bidadari Binjai kini telah menghadirkan pelayanan Rehabilitasi Medik (Fisioterapi) per- 1 Februari 2023. Pelayanan Fisioterapi sendiri ialah pelayanan yang ditujukan kepada individu atau kelompok untuk megembangkan, memelihara dan memulihkan gerak serta fungsi tubuh sepanjang hidup pasien. (Permenkes RI No. 65 Tahun 2015)

Dalam Pelayanan Rehabilitasi Medik RSU Bidadari Binjai memberikan pelayanan  dianta lain:
1. Penanganan Masalah Saraf, otot dan sendi
2. Rehabilitasi Pasca Stroke
3. Rehabilitasi Pasca Operasi
4. Parkinson''s Disease
5. Membantu permasalahan struktur tulang (Skliosis, Kifosis, Rematik, Frozen Shoulders).
6. Cidera Olahraga
7. Osteoarthritis
8. Bells Palsy
9. Nyeri Pergelang tangan.

Diisi oleh tenaga terapis kami yang berpenngalaman dibidangnya dan juga dokter spesialis Kedokteran Fisik dan Rehabilitasi oleh dr.Benni Azhari, M.Ked, Klin, Sp.KFR. Pasien dapat berkonsultas dengan dokter terlebih dahulu sebelum mendapatkan pelayanan yang sesuai dengan indikasi medisnya. Jadwal dokter untuk poliklinik Rehabilitasi medik tersedian pada Selasa (14.00 s/d 17.00 WIB), Rabu (08.00 s/d 12.00 WIB), Kamis (14.00 s/d 17. 00 WIB).

Salam Sehat,
RSU Bidadari

Kesehatan Anda Merupakan Prioritas Utama Kami', NULL, 'news-231124-a3812d06d9.jpg'),
('NEWS-03', 'RUMAH SAKIT UMUM BIDADARI BINJAI MEMPERINGATI HARI GINJAL SEDUNIA TAHUN 2023', 'Rumah sakit Bidadari turut dalam memperingati Hari Ginjal Sedunia dengan turut ikut serta berkampanya pentingnya kesehatan Ginjal. Hari ginjal sedunia atau World Kidney Day (WKD) merupakan acara rutin yang diperingati setiap tahunnya pada hari Kamis di minggu kedua dibulan Maret. Pada tahun 2023 hari ginjal sedunia jatuh pada tanggal 9 Maret 2023. Tema WKD Tahun ini yaitu "Kidney Health for All-Preparing for The Unexpected, Supporting the Vulnerable!" atau "Ginjal sehat untuk semua, antipasi bencana, Lindungi yang Beresiko".

Peringatan WKD sebagai bentuk Kampaye Global dalam Upaya meningkatkan kesadaran setiap orang mengenai pentingnya ginjal bagi kesehatan secara menyeluruh dan mengurangi frekuensi serta dampak penyakit ginjal maupun ganguan ginjal diseluruh dunia. ', NULL, 'news-231124-2246e217eb.jpg'),
('NEWS-04', 'VISITASI PENILAIAN KESESUAIN PELAYANAN DIALISIS DI RUMAH SAKIT UMUM BIDADARI BINJAI', 'Pada  Senin, 6 Februari 2023 telah dilaksananakan kunjungan atau visitasi penilaian kesesuain
Pada pelayanan unit dialisis di Rumah Saki Umum Bidadari Binjai, dalam kunjungan ini turut
Hadir dari Perwakilan Kementrian Kesehatan Republik Indonesia, Dinas Kesehatan Provinsi Sumatera Utara dan Penefri Wilayah Sumatera Utara.
', NULL, 'news-231124-58b8f6c5eb.jpg'),
('NEWS-05', 'RUMAH SAKIT UMUM BIDADARI BINJAI BERPARTISIPASI DALAM KEGIATAN HUT PPNI KE-49 DIADAKAN OLEH PPNI DPD KOTA BINJAI', 'Peringatan Hari Perawat Nasional bertepatan dengan Hari Ulang Tahun (HUT)  Persatuan Perawat Nasional Indonesia (PPNI) yaitu pada tanggal 17 Maret. Peringatan Hari Perawat Nasinal yang ke- 49 kali ini mengangkat tema  "Gapai Sejahtera dengan Profesionalisme.

Pada tahun ini Rumah Sakit Umum Bidadari Binjai turut berpartisipasi dalam perayan HUT PPNI ke- 49 yang diadakan oleh PPNI DPD Kota Binjai. Dalam kegiatan tersebut mewakili seluruh perawat RSU Bidadari mengikuti serangkain kegiatan lomba antar perawat  sekota binjai dan berhasil membawa pulang kemenangan diantaranya adalah:
1. Juara 1 Cerdas Cermat
2. Juara 3 Perawat Teladan.
', NULL, 'news-231124-fb51f5b09e.jpg'),
('NEWS-06', 'RUMAH SAKIT UMUM BIDADARI BINJAI MEMPEROLEH JUARA 2 LOMBA POSTER KATEGORI RUMAH SAKIT', 'Rumah Sakit Umum Bidadari iukt serta dalam Lomba Poster Ilmiah Kategori Rumah Sakit dengan Judul "Pelaksanaan Evaluasi Pelayanan Prioritas Standar Pelayanan Kedokteran Rumah Sakit Umum BidadarI Periode Januari - Juni Tahun 2022" dalam kegiatan LARSI 1st Annual Metting Tahun 2023 dan berhasil mendapatkan Juara II.  Kegiatan ini diadakan Pada 16 - 17 Maret tahun 2023 dan dilaksanakan di The Alana Yogyakarta Hotel & Convention Centre.', NULL, 'news-231124-235c0462ab.jpg'),
('News-07', 'INFORMASI PERATURAN NAIK KELAS RAWAT INAP BPJS KESEHATAN', 'Sehubung dengan terbitnya Peraturan Mentri Kesehatan (PERMENKES) No. 3 Tahun 2023, Maka untuk Pasien Rawat Inap dengan Penjamin BPJS Kelas III, tidak diperkenankan untuk naik kelas rawat inap, bila pasien menginginkan naik kelas maka penjamin BPJS-nya GUGUR dan menjadi (Penjamin UMUM).
Serta untuk penjamin BPJS Kesehatan Kelas II diperkenankan untuk naik sampai dua tingkat ke kelas VIP.
Peraturan ini telah berlaku mulai pelayanan per-tanggal 24 Januari 2023.', NULL, 'news-241114-91da3fb4c5.jpg'),
('News-08', 'RSU BIDADARI BINJAI TELAH MENERIMA NIK/KTP UNTUK AKSES PELAYANAN KESEHATAN', 'Sesuai Janji Layanan Jaminan Kesehatan (JKN) Rumah Sakit Umum Bidadari Binjai menerima  NIK/KTP untuk Pendaftaran Pelayanan pada Rawat Jalan ataupun Rawat Inap. 
Demi mewujudkan transformasi layanan yang Mudah, Cepat dan Setara.', NULL, 'news-231125-cf304c6075.jpg'),
('NEWS-09', 'SOSIALISASI DAN KORDINASI IMPLEMENTASI TRANSFORMASI MUTU LAYANAN BERBASIS MOBILE JKN BPJS KESEHATAN KC MEDAN DI RSU BIDADARI BINJAI', 'Bpjs Kesehatan Kantor  Cabang Medan telah melakukan kegiatan di RSU Bidadari Binjai  pada Selasa, 11 April 2023. Kegiatan tersebut merupakan Pertemuan Sosialisasi dan Kordinasi Bersama Tim Pengendalian Mutu Layanan Rumah Sakit dalam Implementasi Transformasi Mutu Layanan Berbasis Mobile JKN.', NULL, 'news-231125-fe7ff5756e.jpg'),
('NEWS-10', 'RUMAH SAKIT UMUM BIDADARI BINJAI BERPARTISIPASI MEMFASILITASI TENAGA KESEHATAN DALAM KEGIATAN SUNAT MASAL DISELENGGARAKAN DINAS KESEHATAN KOTA BINJAI DAN BAZNAS', 'Rumah Sakit Umum Bidadari Binjai turut Berpartisipasi dalam kegiatan sunat massal di kota Binjai dengan mengirimkan beberapa tenaga kesehatan  yang terdiri dari tiga perawat UGD. Kegiatan sunat masal ini diselenggarakan oleh Dinas Kesehatan Kota Binja dan Baznas. pada Senin, 26 Juni 2023.', NULL, 'news-231125-accf110ced.jpg'),
('NEWS-11', 'PENILAIAN TOP 5 FAST COMPETITION OLEH BPJS PUSAT DI RSU BIDADARI BINJAI', 'Rumah Sakit Bidadari Binjai telah berpartisispasi dalam FAST COMPETITION Fasilitas Kesehatan tahun 2023 yang diadakan oleh BPJS Kesehatan. Dalam kompetisi ini RSU Bidari Binjai mengirimkan dua video dengan thema video "Layanan Inspiratif Fasilitas Kesehatan Kepada Peserta BPJS". Penilaian yang telah dilakukan sejak Juni s/d Juli berhasil membawa RSU Bidadari Binjai masuk sebagai TOP 5 Nasional.

Pada Selasa, 1 Agustus 2023 Tim pusat BPJS Kesehatan melalukan visitasi dalam rangka penilaian secara langsung di Rumah Sakit Umum Bidadari Binjai sebagai TOP 5 Nasional. Rumah sakit umum Bidadari Binjai mendukung penuh Digitalisasi Pelayanan guna efektifitas dan efesiensi pelayana pada peserta JKN. Sebagai Bentuk Transformasi Mutu Layanan untuk mencapai pelayanan  yang Mudah , Cepat dan Setara.', NULL, 'news-231125-fa2aea894d.JPG'),
('NEWS-12', 'PAKET PEMERIKSAAN KESEHATAN RUMAH SAKIT UMUM BIDADARI BINJAI', 'Saat ini untuk para sahabat sehat yang ingin melakukan pemeriksaan kesehatannya  sudah bisa dilakukan di RSU Bidadari Binjai. Kami memberikan penawaran Diskon sampai dengan 50?ngan syarat dan ketentuan berlaku.  Beberapa paket yang kami tawarkan diantara lain:

1. Paket Standar yang tediri atas pemeriksaan Gula Darah Puasa, Kolestrol Total, HDL, LDL, Trigliserida,  dan Asam Urat. dengan harga paket pemeriksaan awal Rp.805.000 setelah diskon hanya Rp. 400.000. sudah masuk gratis konsultasi dengan dokter spesis penyakit dalam atau Spesialis Jantung dengan indikiasi medis.

2.Paket Standar yang tediri atas pemeriksaan Hematologi lengkap, Gula Darah Puasa, Kolestrol Total, HDL, LDL, EKG, Trigliserida, asam urat, dan SGOT, SGPT dengan harga paket pemeriksaan awal Rp 1.175.000 setelah diskon hanya Rp. 750.000. sudah masuk gratis konsultasi dengan dokter spesis penyakit dalam atau Spesialis Jantung dengan indikiasi medis.

3.Paket Silver yang tediri atas pemeriksaan Hematologi lengkap, Gula Darah Puasa, Kolestrol Total, HDL, LDL, EKG, Trigliserida, asam urat, dan SGOT, SGPT, ureum, keratinin, Analisa Urine, Pemeriksaan Rotgen Dada/Thorax dengan harga paket pemeriksaan awal Rp 1.890.000 setelah diskon hanya Rp. 1.000.000. sudah masuk gratis konsultasi dengan dokter spesis penyakit dalam dan Spesialis Jantung dengan indikiasi medis.

4.Paket Gold yang tediri atas pemeriksaan Hematologi lengkap, Gula Darah Puasa, HbA1c,  Kolestrol Total, HDL, LDL, EKG, Trigliserida, asam urat, dan SGOT, SGPT, T3 dan T4, ureum, keratinin, Analisa Urine, Albumin, Globulin, Bilirubin total, HBsAG dan Pemeriksaan Rotgen Dada/Thorax dengan harga paket pemeriksaan awal Rp 3.325.000 setelah diskon hanya Rp. 1.700.000. sudah masuk gratis konsultasi dengan dokter spesis penyakit dalam dan Spesialis Jantung dengan indikiasi medis.

5.Paket Platinum yang tediri atas pemeriksaan Hematologi lengkap, Gula Darah Puasa, HbA1c,  Kolestrol Total, HDL, LDL, EKG, Trigliserida, asam urat, dan SGOT, SGPT, T3 dan T4, ureum, keratinin, Analisa Urine, Albumin, Globulin, Bilirubin total, HBsAG dan Pemeriksaan Rotgen Dada/Thorax , USG Upper Abdoment dan USG Lower dengan harga paket pemeriksaan awal Rp 4.160.000 setelah diskon hanya Rp. 2.500.000. sudah masuk gratis konsultasi dengan dokter spesis penyakit dalam dan Spesialis Jantung dengan indikiasi medis.

Ayo, Ketahui kesehatan terkini anda melalui pemeriksaan kesehatan di RSU Bidadari Binjai.
NB: Paket belum termasuk obat-obatan, serta untuk pelaksanaan dengan perjajainjai. informasi lebih lanjut dapat menghubungi nomor pelayanan whatshapp kami di +62 812 6932 8888.', NULL, 'news-231125-41258ce152.jpg'),
('NEWS-13', 'RSU BIDADARI BINJAI MEMPEROLEH JUARA 1 KATEGORI RS DENGAN UTILITAS TERTINGGI DARI BPJS KETENAGAKERJAAN CABANG BINJAI', 'Hari pelanggan nasional diperingati setiap tahunnya pada tanggal 4 September. 
Perusahaan-perusahaan di seluruh Indonesia merayakan Hari Pelanggan Nasional (HPN) untuk menghargai dan menghormati peran penting pelanggan dan mitra dalam kesuksesan perusahaan. Dalam peringatan tersebut BPJS Ketenagakerjaan salah satu mitra Rumah Sakit Bidadari Binjai menggelar acara untuk memperingati hari pelanngan nasional serta dalam kegitaan ini Rumah Sakit Bidadari Binjai memperoleh juara satu Kategori Rumah Sakit dengan Utilitas trtigi menurut BPJS Ketenagakerjaan Kota Binjai. 
Penghargaan yang diberikan menjadikan RSU Bidadari akan terus berusaha berbenah dalam memberikan pelayanan yang terbaik bagi warga kota binjai dan sekitarnya. Terimakasih atas kepercayaan kepada RSU Bidadari Binjai.', NULL, 'news-231125-46053bc71d.jpg'),
('NEWS-14', 'PENYERAHAN HADIAH LOMBA FAST COMPETITION FASKES TAHUN 2023 OLEH BPJS KESEHATAN KEPADA RSU BIDADARI BINJAI SEBAGAI JUARA TERFAVORIT', 'Rumah Sakit Umum Bidadari Binjai keluar sebagai Juara Favorite pada Kompetisi FAST Competition Faskes Tahun 2023 yang diselenggarakan oleh BPJS Kesehatan. FAST Competition merupakan kompetisi strategi peningkatan mutu layanan di Fasilitas Kesehatan merujuk pada program Transformasi Mutu Layanan Nasional. Kegiatan yang bertemakan ''Strategi Peningkatan Mutu Layanan JKN yang Mudah, Cepat dan Setara'' ini menjadi bagian dari rangkaian HUT BPJS Kesehatan ke-55. Rumah Sakit Umum Bidadari Binjai berkompetisi secara nasional dan merupakan satu satunya wakil dari Sumatera Utara dan Aceh yang maju sampai dengan babak final.

Fast Competition Faskes Tahun 2023 dimulai sejak 05 Juli 2023, dimulai dari babak penjurian finalis, top 25 Nasional, Top 5 Nasional hingga penilaian Onsite berupa kunjungan Visitasi dari BPJS Pusat yang telah dilaksanakan pada tanggal 1 Agustus Tahun 2023.

Pada kompetisi ini Rumah Sakit Umum Bidadari menampilkan 2 video yang menunjukkan layanan inspiratif Fasilitas Kesehatan kepada peserta JKN, dan implementasi Fasilitas Kesehatan terhadap maklumat Janji Layanan JKN. RSU Bidadari Binjai mendukung penuh digitalisasi pelayanan guna efektifitas dan efisiensi pelayanan dalam melaksanakan Transformasi Mutu Layanan. dalam pelayanan saat ini RSU Bidadari melakukan optimalisasi penggunaan Mobile JKN yang dapat menurunkan antrian dalam pelayanan serta meningkatkan kepuasan pasien.

RSU Bidadari berterimakasih atas dukungan PT. Bidadari Medikal Nusantara, Bapak Walikota Kota Binjai, Drs H. Amir Hamzah M.AP, Jajaran BPJS Kesehatan Kantor Cabang Medan, serta seluruh masyarakat kota Binjai serta Seluruh Civitas hospitalia RS Bidadari Grup atas dukungan yang luar biasa selama RSU Bidadari Binjai mengikuti Kompetisi ini.
', NULL, 'news-231125-e22bb73e0e.jpg'),
('NEWS-15', 'PERESMIAN SERENTAK SELURUH INDONESIA LOKET/TEMPAT PELAYANAN INFORMASI DAN PORTAL QR BPJS KESEHATAN (POROS)', 'Rumah Sakit Umum Bidadari Binjai mengupayakan perbaikan pada area pemberian informasi dan penanganan pengaduan peserta di FKRTL melalui peyedia tempat/loket pelayanan informasi BPJS Kesehatan di FKRTL merupakan upaya untuk menjawab kebutuhan peserta dalam kemudahan mendapatkan akses serta informasi serta kecepatan dan kepastian dalam memperoleh tindak lanjut atas penyampaian pengaduan terkait pelayanan dalam program JKN di FKRTL melalui dibukannya loket pelayanan informasis erta Portal QR BPJS Kesehatan yang mudah diakses pasien dan Keluarga.
Peresmian loket pemberian informasi ditandai dengan Launsing Signase Pelayanan Informasi BPJS Kesehatan yang dilakukan serentak di seluruh Indonesia pada Jum''at, 29 September 2023.', NULL, 'news-231125-6c5b084b63.jpg'),
('NEWS-16', 'PENYERAHAN PIAGAM PENGHARGAAN FASKES BERKOMITMEN TAHUN 2023 OLEH BPJS KESEHATAN KEDEPUTIAN WILAYAH 1 KEPADA RSU BIDADARI BINJAI', 'ada Senin, 3 Oktober 2023 RSU Bidadari Binjai telah menerima Piagam Penghargaan Sebagai Fasilitas Kesehatan Berkomitmen tahun 2023 Kategori Kelas C yang diberikan Oleh BPJS Kesehatan Kedeputian Wilayah 1 Sumatera Utara dan Aceh. RSU Bidadari Binjai Mengucapkan Terimakasih Kepada BPJS Kedeputian Wilayah 1 atas Penghargaaan Ini. 

Melalui terpilihnya RSU Bidadari Binjai menjadi salah satu FKRTL yang ikut serta dalam penilaian Faskes Berkomitmen Tahun 2023 RSU Bidadari Binjai akan selalu siap dan terus bersemangat untuk berupaya memberikan pelayanan berkomitmen kepada masyarakat melalui implementasi janji layanan serta menghadirkan inovasi yang bertujuan meningkatkan kenyamanan pasien. Sehingga dapat mewujudkan tercapainya transformasi mutu layanan yang Mudah, Cepat dan Setara.', NULL, 'news-231127-7f499589b9.jpg'),
('NEWS-17', 'RUMAH SAKIT UMUM BIDADARI BINJAI TERPILIH SEBAGAI BRAND AMBASSADOR RUMAH SAKIT TIPE C BERKOMITMEN ', 'RSU Bidadari Binjai telah menerima Piagam Penghargaan Sebagai Brand Ambassardor Rumah Sakit Berkomitmen tahun 2023 Kategori Kelas C yang diberikan Oleh BPJS Kesehatan Kantor Cabang Medan.  Sekaligus penyerahan Piagam penghargaan FKRTL Terbaik dalam lomba Video Fast Competition Tahun 2023 tingkat Kantor Cabang Medan.

Rsu Bidadari Binjai Mengucapkan Terimakasih Kepada BPJS Kantor Cabang Medan atas Penghargaaan Ini. 

Melalui terpilihnya RSU Bidadari Binjai menjadi salah satu FKRTL yang ikut serta dalam penilaian Faskes Berkomitmen Tahun 2023 Rsu Bidadari Binjai akan selalu siap dan terus bersemangat untuk berupaya memberikan pelayanan berkomitmen kepada masyarakat melalui implementasi janji layanan serta menghadirkan inovasi yang bertujuan meningkatkan keyamanan pasien. Sehingga dapat mewujudkan transformasi mutu layanan yang Mudah, Cepat dan Setara.', NULL, 'news-231127-79e90f66ba.jpg'),
('NEWS-18', 'KEGIATAN BAKTI SOSIAL RSU BIDADARI BINJAI BERSAMA TNI DALAM ACARA PENUTUPAN TIM MANUNGGAL MEMBANGUN DESA (TMMD) KE- 118', 'Pada Kamis, 19 Oktober 2023 RSU Bidadari Binjai bersama TNI telah melaksanakan kegiatan Bakti Sosial dalam acara Penutupan Tim Manunggal Membangun Desa (TMMD) ke-118 Tahun 2023. Tampak antusiasme masyarakat pada stand pengobatan RSU Bidadari Binjai. 

Turut hadir juga memberikan pelayanan dr. Erni Erdoris Ginting Sp.PD, dr. Fitriani dan dr josapat.', NULL, 'news-231127-d04752188a.jpg'),
('NEWS-19', 'HARI DOKTER NASIONAL TAHUN 2023', 'Hari Dokter Nasional diperingati setiap tanggal 24 Oktober setiap tahunnya. Peringatan ini sekaligus merayakan Hari Ulang Tahun (HUT) Ikatan Dokter Indonesia (IDI).

Pada tahun ini IDI mengusung tema HUT ''Memperkuat Ikatan Tradisi Luhur, Bersatu dan Mengabdi untuk Rakyat Indonesia''. Tema tersebut memiliki makna bahwa IDI akan terus hadir di tengah-tengah masyarakat dalam upaya meningkatkan derajat kesehatan masyarakat, menuju masyarakat yang sehat.

Kami segenap keluarga besar RSU Bidadari Binjai 
Mengucapkan:
Selamat Hari Dokter Nasional!', NULL, 'news-231127-ca7875126b.jpg'),
('NEWS-20', 'PELAKSANAAN KREDENSIAL RSU BIDADARI BINJAI DENGAN BPJS KESEHATAN TAHUN 2023', 'Telah dilaksanakan Kredensial Rumah Sakit Umum Bidadari Binjai dengan BPJS Kesehatan serta Dinas Kesehatan Kota Binjai dan PERSI pada Jum''at, 20 Oktober 2023', NULL, 'news-231127-1c2653c18c.jpg'),
('NEWS-21', 'LAYANAN OPERASI KATARAK METODE PHACOEMULSIFIKASI RSU BIDADARI BINJAI', 'Rumah Sakit Umum Bidadari Binjai memiliki berbagai layanan unggulan, dan salah satu layanan unggulan tersebut adalah Layanan Operasi Katarak dengan Metode Phacoemulsifikasi yang dilakukan oleh Dokter Spesialis Mata yang Terlatih dan Profesinal.

Teknik operasi Phacoemulsifikasi memiliki beragam keunggulan karena merupakan teknik operasi paling mutakhir, cepat dan aman. Untuk mendapatkan pelayanan serta konsultasi dengan dokter mata kami sahabat sehat juga sudah bisa mendaftar melalui JKN Mobile loh. 

*Jadwal Dokter Spesialis Mata:
dr. Syarifah Yusriani, M.Ked (Oph), Sp.M
Senin & Rabu : 13.45 s/d 17. 30 WIB
Selasa : 14.15 s/d 17.30 WIB
Jum''at : 11.45 s/d 15.00 WIB', NULL, 'news-231129-45dc38abc8.jpg'),
('News-22', 'RUMAH SAKIT UMUM BIDADARI BINJAI TELAH MELAYANI PROGRAM UHC (UNIVERSAL HEALTH COVERAGE) PRIORITAS KOTA BINJAI', '* Launcing dan Supervisi Program UHC RSU Bidadadari Binjai*

UHC (Universal Health Coverage) adalah sistem penjaminan kesehatan yang memastikan semua penduduk telah terdaftar sebagai Peserta Program JKN sesuai dengan ketentuan yang berlaku. Per tanggal 28 Agustus 2025 Pemerintah Kota Binjai telah mencanangkan program Universal Health Coverage (UHC) dan pada tanggal 22 Agustus 2025 telah dilakukan launcing program UHC bagi warga Binjai. RSU Bidadari Binjai turut hadir serta mendukung program tersebut sebagai fasilitas kesehatan yang melayani UHC.

Pada tanggal 23 September 2025 turut dilaksanakan supervisi kunjungan yang dilakukan oleh kepala Dinas Kesehatan Kota Binjai untuk meninjau secara langsung rumah sakit yang telah menjalankan program UHC. 
Kujungan tersebut menjadi motivasi bagi RSU Bidadari Binjai untuk terus meningkatkan pelayanan yang lebih baik lagi.', '2025-09-26 01:46:10', 'news-250926-8cd14f0054.jpg'),
('News-23', 'GRAND OPENING RUMAH SAKIT UMUM PUTRI BIDADARI ACEH', 'Rumah Sakit Umum (RSU) Putri Bidadari Aceh di bawah naungan PT Ade Putri Medikal Nusantara Bidadari Group resmi dibuka ditandai dengan grand opening di Jalan Soekarno-Hatta, Gampong Lamreung, Kecamatan Darul Imarah, Aceh Besar, Kamis (23/10/2025). Direktur Utama PT Ade Putri Medikal Nusantara, Firmansyah SE MARS mengatakan, tujuan mulia pembangunan rumah sakit ini yakni membantu Pemerintah Aceh dalam investasi bidang kesehatan. 


', '2025-11-11 01:46:21', 'news-251111-213e024750.jpg');

INSERT INTO poli (id_poli, nama_poli, ket, images) VALUES
('P01', 'POLIKLINIK BEDAH UMUM', 'Merupakan unit rawat jalan yang disediakan oleh RSU BIDADARI BINJAI. Unit rawat jalan ini merupakan unit pelaksana teknis pelayanan kesehatan dalam proses pembedahan umum. Pelayanan yang ditangani di Poli Bedah Umum adalah operasi kecil, operasi hernia, usus buntu, haemoroid (wasir), konsultasi seputar proses pembedahan, dan lain - lain. Unit ini menyediakan ruang praktek spesialis dan ruang tunggu yang nyaman bagi pasien. Saat ini kami didukung oleh dokter-dokter spesialis bedah umum yang berpengalaman dibidangnya, serta ditunjang peralatan medis yang modern, lengkap dan memadai, pemberian pelayanan bagi Anda dan keluarga menjadi lebih optimal.


', 'poli-250711-a90028bb63.JPG'),
('P02', 'POLIKLINIK MATA', 'Tim dokter spesialis mata serta konsultan dari berbagai keahlian RSU BIDADARI BINJAI siap memberikan konsultasi mata terpadu dalam mengatasi berbagai permasalahan mulai dari radang mata, katarak, glaukoma, layanan rekonstruksi mata, dan lainnya. Tindakan yang dilakukan mulai dari pengukuran tekanan bola mata dengan Tonometri, pemeriksaan untuk melihat luasnya kerusakan saraf mata dengan Perimetry, pemeriksaan tajam penglihatan/ Visus, pengukuran minus/ silinder mata dengan refraksi, pemeriksaan untuk mendeteksi dini kelainan pada kornea mata dengan Slit Lamp. Hadir pula teknik Phaco Emulsi?casi untuk bedah katarak dengan sayatan +/- 2 mm dan risiko minimal.', 'poli-250710-0e00a4e8f1.JPG'),
('P03', 'POLIKLINIK PENYAKIT DALAM', 'RSU BIDADARI BINJAI memiliki poli-poli spesialis, diantaranya adalah poli penyakit dalam. Poliklinik penyakit dalam ini memberikan pelayanan penanganan masalah kesehatan organ dalam tanpa bedah, seperti diabetes melitus, sakit ginjal, sakit lambung, lever, dan lainnya. Ditangani oleh dokter ahli penyakit dalam yang profesional dan berpengalaman dibidangnya serta ditunjang dengan fasilitas yang memadai sesuai dengan kebutuhan pasien, keluhan pasien mengenai penyakit dalam dapat ditangani dengan baik.', 'poli-250710-2610b3788d.JPG'),
('P04', 'POLIKLINIK THT (TELINGA HIDUNG TENGGOROKAN)', 'Poli THT RSU BIDADARI BINJAI membantu Anda dalam memberikan solusi masalah kesehatan Anda khususnya pada telinga, hidung dan tenggorokan. Melalui dokter spesialis THT yang ahli di bidangnya, serta ditunjang peralatan medis yang modern, lengkap dan memadai, pemberian pelayanan bagi Anda dan keluarga menjadi lebih optimal dan yang termasuk dalam tindakan diantaranya adalah:
• Endoscopy THT
• Tonsitektomi (Operasi Amandel)
• Turbinektomi (Operasi Sinusitis', 'poli-250710-d2d2a2d3f1.JPG'),
('P05', 'POLIKLINIK ANAK', 'Konsultasi dokter spesialis anak dilakukan setiap hari sesuai dengan jam praktek dokter masing-masing. Masalah kesehatan seperti kelainan pada anak dan bayi, Masalah Gastroenterologi (pencernaan), masalah keterlambatan tumbuh kembang anak, kasus Perinatologi (bayi premature, kuning, infeksi), Trauma akibat kecelakaan atau jatuh, penyakit infeksi (panas, diare, thypoid, demam berdarah, campak, cacar air), dan masalah kesehatan anak lainnya dapat ditangani di RSU Bidadari dengan dokter yang handal, tenaga medis dan paramedis yang terampil, serta fasilitas dan sarana pendukung yang lengkap.', 'poli-250710-9ccc72867a.JPG'),
('P06', 'POLIKLINIK OBGYN', 'RSU BIDADARI BINJAI memiliki poli kebidanan dan kandungan yang melayani pemeriksaan kehamilan, penyakit kandungan dan persalinan. Sarana penunjang yang juga kami sediakan untuk mendukung klinik kebidanan dan kandungan ini adalah fasilitas USG 4D untuk mengetahui perkembangan janin pada si ibu hamil. Pada masa sebelum persalinan, kelas prenatal juga diberikan sebagai pengetahuan dan persiapan kehamilan dan persalinan. Selain itu kami juga memiliki klinik laktasi untuk mengetahui bagaimana cara mempersiapkan dan memberikan ASI yang baik dan benar.', 'poli-250711-6287bb6ca0.JPG'),
('P07', 'POLIKLINIK JANTUNG', 'Di RSU BIDADARI BINJAI terdapat klinik konsultasi dan fasilitas Check  Up  Jantung  yang  didukung  dengan  peralatan-peralatan khusus, seperti pemeriksaan Echocardiography, Elektrokardiogra? maupun Treadmill. Selain Klinik Konsultasi dan Check up Jantung.', 'poli-250711-a889d4a7b4.JPG'),
('P08', 'POLIKLINIK RADIOLOGI', 'Poliklinik radiologi adalah bagian dari fasilitas kesehatan, seperti rumah sakit, yang menyediakan layanan pemeriksaan dan interpretasi gambar medis untuk membantu dokter dalam mendiagnosis dan memantau kondisi pasien. Poliklinik ini menggunakan berbagai teknologi pencitraan medis, seperti sinar-X, USG, CT scan, dan MRI, untuk menghasilkan gambar bagian dalam tubuh pasien. ', 'poli-250711-a154567697.JPG'),
('P09', 'POLIKLINIK BEDAH SARAF', 'Poli Bedah Saraf menangani kondisi yang mempengaruhi sistem saraf dan mencakup prosedur bedah seperti operasi saraf, pemasangan stimulasi saraf, dan pengangkatan tumor otak. Tim medis terdiri dari ahli bedah saraf dan perawat yang bekerja sama dengan tim medis lainnya untuk memberikan perawatan holistik dan terintegrasi bagi pasien.', 'poli-250711-47985cdc52.JPG'),
('P10', 'POLIKLINIK PARU', 'Poliklinik Paru RSU BIDADARI BINJAI meliputi : konsultasi asma dan Penyakit Paru Obstruktif Kronik (PPOK), terapi inhalasi penyakit tuberculosis, infeksi paru dan pernapasan, pemeriksaan faal paru, konsultasi gangguan tidur, konsultasi berhenti merokok. Dilengkapi dengan alat diagnosa, spirometri, dan penanganan lebih lanjut oleh para dokter ahli dan paramedis yang terampil, serta fasilitas dan sarana pendukung yang lengkap.', 'poli-250711-125f825c76.JPG'),
('P12', 'POLIKLINIK SPESIALIS KULIT DAN KELAMIN', 'RSU BIDADARI BINJAI menyediakan pelayanan kesehatan kulit dan kelamin yang ditangani oleh tim dokter spesialis kulit dan kelamin profesional. Ketersediaan poliklinik kulit & kelamin di RSU BIDADARI BINJAI ditujukan untuk membantu pasien yang memiliki permasalahan kulit dan penyakit kelamin dengan didukung beberapa dokter ahli spesialis kulit dan kelamin yang kompeten serta dibantu tim medis yang terampil. Tidak hanya itu, poliklinik ini ditunjang dengan ketersediaan peralatan dan fasilitas ruang konsultasi, tindakan, perawatan kulit yang memadai.', 'poli-250711-ec57ad780c.JPG'),
('P13', 'POLIKLINIK SARAF', 'poli syaraf RSU BIDADARI BINJAI memberikan pelayanan saraf yang prima, efektif dan e?sien terhadap pasien dengan keluhan atau masalah seperti nyeri kepala, leher, pinggang, vertigo, cedera kepala, perdarahan otak, stroke dan organ saraf lainnya. Dilengkapi dengan peralatan medis yang sesuai kebutuhan pasien.edah saraf seperti cidera kepala, adanya kelainan susunan saraf otak, sumsum tulang belakang, pembuluh darah dan stroke perdarahan.
 ', 'poli-250711-99456a3764.JPG'),
('P16', 'UNIT REHABILITASI MEDIK (FISIOTERAPI)', 'RSU Bidadari Binjai telah menyediakan pelayanan rawat jalan upaya rehabilitatik yang pertama kali dibuka pada 01 Februari 2023 yaitu rehabilitasi medik (Fisioterapi). Fisioterapi adalah tindakan atau terapi rehabilitasi yang dilakukan pada pasien pasca mengalami kondisi tertentu, seperti penyakit atau cedera. Pada dasarnya, fisioterapi dibutuhkan untuk mengembalikan fungsi normal tubuh dan dapat beraktivitas seperti biasa. Terapi ini dapat membantu pasien meringankan rasa sakit dan kekakuan, mempercepat pemulihan, dan meningkatkan kualitas hidup.', 'poli-250711-ef029a1f68.JPG'),
('P17', 'POLIKLINIK GIGI', 'Poli Gigi dan Mulut RSU BIDADARI BINJAI melayani pasien dengan permasalahan gigi, gusi, rahang dan mulut. Poli ini ditunjang fasilitas dental unit terkini dan memperhatikan prinsip general precaution, septic-aseptic dan penggunaan peralatan sekali-pakai / disposable untuk mencegah penularan penyakit dari pasien melalui peralatan gigi atau pasien ke dokter dan sebaliknya. Tim dokter gigi yang terdiri dari dokter gigi terlatih akan memberikan pelayanan gigi secara profesional dan berkualitas.', 'poli-250714-adae29a660.JPG'),
('P18', 'PATOLOGI KLINIK', 'RSU Bidadari Binjai telah memiliki Laboratorium Patologi klinik dilengkapi dengan fasilitas modern untuk berbagai jenis pemeriksaan laboratorium, mendukung diagnosis dan pengobatan yang akurat. diantaranya adalah: Hematologi Pemeriksaan hemoglobin, hematokrit, trombosit, hitung jenis. Kimia Klinik Fungsi hati: SGOT, SGPT, bilirubin (total, direk, indirek), albumin, protein total. Fungsi ginjal: Ureum, kreatinin. Kolesterol total, HDL, LDL, trigliserida. Asam urat, glukosa (puasa, 2 jam, toleransi oral). Elektrolit (natrium, kalium, klorida, magnesium, kalsium). HbA1c, LDH, Gamma GT, alkali fosfatase, analisa gas darah, keton darah, laktat.', 'poli-250714-c7111679d7.JPG'),
('P19', 'UNIT DIALISIS', 'Unit dialisis adalah merupakan salah satu unit pelayanan di RSU Bidadari Binjai memberikan pelayanan diperuntukan bagi penderita gagal ginjal kronik yang memerlukan tindakan cuci darah, Unit dialisis RSU Bidadari Binjai pertama kali dibuka pada 01 April 2016 didukung oleh tim kerja yang kompeten terdiri dari spesialis penyakit dalam bersertifikat, dokter umum dan perawat yang bersertifikat Hemodialisis.', 'poli-250714-91131e97b7.JPG');

